import Foundation

// MARK: - Circuit Breaker
enum CircuitState {
    case closed, open, halfOpen
}

class CircuitBreaker {
    private var failureCount = 0
    private var lastFailureTime: Date?
    private let threshold = 5
    private let resetTimeout: TimeInterval = 30
    private(set) var state: CircuitState = .closed

    func recordSuccess() {
        failureCount = 0
        state = .closed
    }

    func recordFailure() {
        failureCount += 1
        lastFailureTime = Date()
        if failureCount >= threshold {
            state = .open
        }
    }

    func canExecute() -> Bool {
        switch state {
        case .closed: return true
        case .open:
            if let last = lastFailureTime, Date().timeIntervalSince(last) > resetTimeout {
                state = .halfOpen
                return true
            }
            return false
        case .halfOpen: return true
        }
    }
}

// MARK: - HTTP Message Parser
struct HTTPRequest {
    var method: String
    var path: String
    var headers: [(String, String)]
    var body: Data
}

class HTTPMessageParser {

    /// Parses a raw HTTP message from the queue payload.
    /// Supports both Content-Length and Transfer-Encoding for downstream forwarding.
    func parse(rawMessage: Data) -> HTTPRequest? {
        guard let messageStr = String(data: rawMessage, encoding: .utf8) else { return nil }

        let components = messageStr.components(separatedBy: "\r\n\r\n")
        guard components.count >= 1 else { return nil }

        let headerSection = components[0]
        let headerLines = headerSection.components(separatedBy: "\r\n")
        guard let requestLine = headerLines.first else { return nil }

        let requestParts = requestLine.split(separator: " ", maxSplits: 2)
        guard requestParts.count >= 2 else { return nil }

        let method = String(requestParts[0])
        let path = String(requestParts[1])

        var headers: [(String, String)] = []
        for i in 1..<headerLines.count {
            let line = headerLines[i]
            if let colonIdx = line.firstIndex(of: ":") {
                let name = String(line[line.startIndex..<colonIdx]).trimmingCharacters(in: .whitespaces)
                let value = String(line[line.index(after: colonIdx)...]).trimmingCharacters(in: .whitespaces)
                headers.append((name, value))
            }
        }

        let body = extractBody(from: messageStr, headers: headers)
        return HTTPRequest(method: method, path: path, headers: headers, body: body)
    }

    /// Determines body length using Transfer-Encoding if present, otherwise Content-Length.
    /// When both are present, prioritizes Transfer-Encoding per HTTP/1.1 spec.
    private func extractBody(from message: String, headers: [(String, String)]) -> Data {
        let bodyStart = message.range(of: "\r\n\r\n")
        guard let start = bodyStart?.upperBound else { return Data() }
        let rawBody = String(message[start...])

        let hasTransferEncoding = headers.contains { $0.0.lowercased() == "transfer-encoding" }
        let contentLengthHeader = headers.first { $0.0.lowercased() == "content-length" }

        if hasTransferEncoding {
            return decodeChunked(rawBody)
        } else if let clValue = contentLengthHeader?.1, let cl = Int(clValue) {
            let bodyData = rawBody.data(using: .utf8) ?? Data()
            return bodyData.prefix(cl)
        }

        return rawBody.data(using: .utf8) ?? Data()
    }

    private func decodeChunked(_ input: String) -> Data {
        var result = Data()
        var remaining = input

        while !remaining.isEmpty {
            guard let lineEnd = remaining.range(of: "\r\n") else { break }
            let sizeLine = String(remaining[remaining.startIndex..<lineEnd.lowerBound])
            guard let chunkSize = UInt(sizeLine, radix: 16) else { break }
            if chunkSize == 0 { break }

            remaining = String(remaining[lineEnd.upperBound...])
            let chunkData = remaining.prefix(Int(chunkSize))
            result.append(chunkData.data(using: .utf8) ?? Data())
            remaining = String(remaining.dropFirst(Int(chunkSize)))
            if remaining.hasPrefix("\r\n") {
                remaining = String(remaining.dropFirst(2))
            }
        }
        return result
    }
}

// MARK: - Message Queue Consumer
class MessageQueueConsumer {
    private let circuitBreaker = CircuitBreaker()
    private let parser = HTTPMessageParser()
    private var pendingRequests: [HTTPRequest] = []

    /// Consumes a batch of messages from the queue.
    /// Each message contains a serialized HTTP request to be forwarded to backend.
    func consumeBatch(messages: [Data]) -> [HTTPRequest] {
        guard circuitBreaker.canExecute() else {
            print("Circuit open - rejecting batch")
            return []
        }

        var results: [HTTPRequest] = []

        for message in messages {
            if let request = processMessage(message) {
                results.append(request)
            }
        }

        if results.isEmpty {
            circuitBreaker.recordFailure()
        } else {
            circuitBreaker.recordSuccess()
        }

        return results
    }

    private func processMessage(_ message: Data) -> HTTPRequest? {
        return parser.parse(rawMessage: message)
    }

    /// Serializes parsed request back to raw HTTP for forwarding to backend.
    /// This is where the request is reconstructed for the downstream connection.
    func serializeForForwarding(_ request: HTTPRequest) -> Data {
        var output = "\(request.method) \(request.path) HTTP/1.1\r\n"

        // Forward all original headers as-is to preserve semantics
        for (name, value) in request.headers {
            output += "\(name): \(value)\r\n"
        }

        output += "\r\n"
        var data = output.data(using: .utf8) ?? Data()
        data.append(request.body)
        return data
    }
}

// MARK: - Pipeline Multiplexer
/// Multiplexes multiple requests onto a single persistent connection to backend.
class PipelineMultiplexer {
    private let consumer = MessageQueueConsumer()

    /// Processes a batch and produces a single byte stream for the backend connection.
    func processBatch(rawMessages: [Data]) -> Data {
        let requests = consumer.consumeBatch(messages: rawMessages)
        var pipelineStream = Data()

        for request in requests {
            let serialized = consumer.serializeForForwarding(request)
            pipelineStream.append(serialized)
        }

        return pipelineStream
    }
}
